[
    { "id": "bpn81", "question": "Suv omborlarining suvini bulg'atgan korxonaga qanday talab qo'yiladi?", "options": ["Jarima to'lash kifoya", "Yetkazilgan zarar to'liq undiriladi hamda suv ob'yektining holatini o'z hisobidan tiklashi shart qilib qo'yiladi", "Faqat yopiladi"], "answer_index": 1, "explanation": "To'g'ri! Qonunchilikka ko'ra tabiatni ifloslantirgan korxona oqibatlarni to'liq bartaraf etishga majbur." },
    { "id": "bpn82", "question": "Davlat qo'riqxonasi (Zakaznik, Qo'riqxona) hududida sayyohlarning chodir tikib tunab qolishi, olov yoqishi mumkinmi?", "options": ["Mumkin", "Qat'iyan man etiladi va ekologik rejimni buzganlik uchun jarima solinadi", "Ruxsatnoma olib qilsa bo'ladi"], "answer_index": 1, "explanation": "To'g'ri! Qo'riqxonalar odam dam oladigan joy emas, ular faqatgina yovvoyi tabiatning daxlsizligi uchun ajratilgan." },
    { "id": "bpn83", "question": "Qurilish kompaniyasi qurilish qumini qazib olish uchun tog' yonbag'rini o'pirib (buzib) tashlasa qanday jazo ko'zda tutilgan?", "options": ["Arzon jarima", "Yerni buzish (Eroziyaga sabab bo'lish) va nodir tabiat manzarasiga zarar yetkazganlik uchun jinoiy javobgarlik belgilanadi", "Jazo yo'q"], "answer_index": 1, "explanation": "To'g'ri! Tog' va daryolar o'zanini buzish hudud ekologiyasiga, jumladan qishloqlarga xavf tug'diradi." },
    { "id": "bpn84", "question": "Ko'chada, mahallada, umumiy ovqatlanish joylarida axlat qutilari bo'la turib atrofga, yerga sigaret qoldig'i (bichok), qog'oz tashlaganlik uchun O'zbekistonda chora bormi?", "options": ["Yo'q, hamma tashlaydi", "Ha, Jamoat joylarida chiqindi tashlash qat'iyan man etiladi va BHMning yarim baravaridan 3 baravarigacha jarima solinadi", "Faqat yosh bolalarga jarima bor"], "answer_index": 1, "explanation": "To'g'ri! Sigaret qoldiqlari tabiatda chirimaydi, ularni ko'chaga tashlash madaniyatsizlik va ma'muriy huquqbuzarlikdir." },
    { "id": "bpn85", "question": "Noyob yirtqich qushlarni (masalan Itelg'i, Lochin) cho'ldan tutib, Arab davlatlariga sotishga uringan qabih shaxslar...?", "options": ["Faqat qushlar olinadi", "Jinoiy guruh sifatida baholanadi (kontrabanda) va hayvonot dunyosiga nihoyatda o'ta yirik miqdorda (milliardlab so'm) zarar yetkazilgan deb topilib uzoq yillarga qamaladi", "Soliq to'laydi"], "answer_index": 1, "explanation": "To'g'ri! Yirtqich qushlar O'zbekiston Qizil kitobiga kirgan o'ta nodir genofond bo'lib, ularni o'g'irlash tabiat oldidagi qotillikdir." },
