    { "id": "bpn87", "question": "Ko'chadagi, uyi yonidagi ko'p yillik chinor va tut daraxtlariga qurilish mollarini, beton plitalarini suyab yoki mixlab qo'yish (daraxtga zarar) jazolanadimi?", "options": ["Yo'q, u o'zining ko'chasi", "Ha, O'simliklar olamiga shikast yetkazganligi (MJtK 79-modda) uchun ma'muriy jarimaga tortiladi", "Faqat ko'chada turibdi"], "answer_index": 1, "explanation": "To'g'ri! Daraxtga har qanday mexanik shikast yetkazish, u ko'chada yoki idora oldida bo'lishidan qat'iy nazar jazolanadi." },
    { "id": "bpn88", "question": "Avtomobil yuvish shoxobchasi (moyka) davlat ichimlik suvi tarmog'iga yashirincha (o'zboshimchalik bilan, hisoblagichsiz) ulanib, ichimlik suvi bilan moshina yuvsa qanday chora ko'riladi?", "options": ["Faqat hisoblagich qo'yiladi", "Ichimlik suvidan isrofgarona va ruxsatsiz foydalanganlik, resurslarni talon-taroj qilganlik aybi bilan tarmoqdan uziladi va katta jarima tortiladi", "Soliq to'laydi"], "answer_index": 1, "explanation": "To'g'ri! Chuchuk va ichimlik suvi taqchil resurs bo'lib, undan avtomobil yuvishda foydalanish jinoyat sanaladi (Texnik suvdan foydalanish shart)." },
    { "id": "bpn89", "question": "Tuproq unumdorligini buzganlik va qishloq xo'jaligi yerlaridan noto'g'ri foydalanib yerning sho'rlanishi va degradatsiyasiga sabab bo'lgan fermer xo'jaligi...", "options": ["O'zining yeri-ku", "Yer qonunchiligini buzganligi uchun jarimaga tortiladi va yer (ijara shartnomasi) undan olib qo'yilishi mumkin", "Jazo yo'q"], "answer_index": 1, "explanation": "To'g'ri! Yer milliy mulk, unga nisbatan e'tiborsizlik qilish iqtisodiy va ekologik sabotajdek gap." },
    { "id": "bpn90", "question": "Uy yoki restoran yonidagi shovqin normasi belgilangan bo'lib (masalan tungi vaqtda), undan oshgan ovoz balandligini ekologlar nima orqali o'lchaydilar?", "options": ["Quloq bilan", "Shumo-mer (Shovqin o'lchovchi maxsus datchiklar) yordamida desibellarda o'lchaydilar. Norma oshsa qat'iy choralar ko'riladi", "O'lchash imkonsiz"], "answer_index": 1, "explanation": "To'g'ri! Zamonaviy ekologiya nazoratida akustik ifloslanish apparatlar yordamida aniq ko'rsatib beriladi." },
    { "id": "bpn91", "question": "Zavod gaz tozalash filtrlari buzilgan holatda ishlab chiqarayotgan tutun miqdori Ekologik me'yordan oshib ketsa, nega qattiq jazo ko'riladi?", "options": ["Odamlarga kasallik yuqadi", "Normadan ortiq (PDK) havoga tashlangan zaharli moddalar soniga qarab (tonnasiga) tabiatga yetkazilgan millionlab (yoki milliardlab) moddiy zarar jarimadan tashqari undirib olinadi", "Faqat jarima solinadi"], "answer_index": 1, "explanation": "To'g'ri! Jarima faqat qonunni buzganning jazosi, Zarar (kompensatsiya) esa u havoga chiqargan gaz uchun davlatga to'lanadigan to'lovdir." },
    { "id": "bpn92", "question": "Noyob hayvonlarni ko'paytirish (pitomniklar) fermasi egasi pitomnikdagi qafasdan yirtqich hayvon (ayiq) larning qochib ketishiga beparvolik qilsa va ular aholiga xavf tug'dirsa kim javobgar bo'ladi?", "options": ["Ayiq javobgar", "Ferma egasi yovvoyi hayvonlarni saqlash xavfsizligi qoidalarini buzganlik va ehtiyotsizlik uchun Jinoyat kodeksi bo'yicha javobgarlikka tortiladi", "Javobgarlik yo'q"], "answer_index": 1, "explanation": "To'g'ri! Xavfli yovvoyi hayvonlarni saqlovchilar doimiy nazorat va o'ta qat'iy xavfsizlik ta'minlashga majburdirlar." },
    { "id": "bpn93", "question": "Davlat o'rmon fondiga kiruvchi to'qayzorlarda ruxsatsiz daraxtlarni kesib, u yerni shudgor qilib ekin ekkan shaxslar...?", "options": ["Hosilni olib ketadi", "Jinoiy javobgarlikka tortiladi, bino-inshootlari buziladi va O'rmon xo'jaligiga yetkazilgan millionlab moddiy ziyon undiriladi", "Yerni o'zlashtiradi"], "answer_index": 1, "explanation": "To'g'ri! O'rmon yerlari faqat davlat mulki bo'lib qoladi, u yerda yer o'zlashtirish o'g'rilikdir." },
    { "id": "bpn94", "question": "Kasbi ovchi (Litsenziyali) bo'lgan shaxs Qizil kitobga kirgan Arxarni (tog' qo'yini) ruxsatsiz otib qo'ysa nima bo'ladi?", "options": ["Kechiriladi, u ovchi", "Kasbidan qat'iy nazar Qizil kitob turlarini ruxsatsiz (kvotasiz) otish Jinoiy Kodeks moddasi sanaladi, uning miltig'i musodara qilinadi va u qamoq jazosiga hukm qilinishi mumkin", "Faqat litsenziyasi olinadi"], "answer_index": 1, "explanation": "To'g'ri! Qizil kitob turlariga nisbatan har qanday noqonuniy ov qat'iyan man etiladi, ularning maqomi ovchilar tomonidan yaxshi bilinishi shart." },
    { "id": "bpn95", "question": "Suv tubidagi zaharli balchiq yoki loyni olib, uni shunchaki qo'shni ekin maydoniga tashlagan meliorator-quruvchi javobgarlikka tortiladimi?", "options": ["Yo'q, u ishni bajardi", "Ha, zaharli balchiq (masalan, og'ir metallar to'plangan loy) tuproqni kuchli zaharlagani uchun u Ekologik xavfsizlik qoidalarini buzishda ayblanadi", "Loy ekinlarga foyda"], "answer_index": 1, "explanation": "To'g'ri! Chiqindi balchiqlar ko'pincha zaharli qoldiqlar (pestisidlar) ni o'zida saqlaydi, ularni ko'r-ko'rona yerga yoyish xavflidir." },
    { "id": "bpn96", "question": "Agar biror korxona havoga tasodifan yirik miqdorda xavfli zahar (masalan ammiak yoki xlor) chiqarib yuborsa va ekologiya qo'mitasidan bu haqda yashirsa (xabar bermasa) nima bo'ladi?", "options": ["Tekshirmasa bilishmaydi", "Avariya (halokat) holati haqida hukumat va aholiga axborot bermaslik, favqulodda vaziyatni yashirish eng og'ir jinoyatlardan hisoblanadi (Jk 196)", "Korxona sir saqlashga haqli"], "answer_index": 1, "explanation": "To'g'ri! Har qanday ekologik favqulodda vaziyatni yashirish aholi hayotiga qasddan qilingan xavf sifatida baholanadi." },
    { "id": "bpn97", "question": "Sanoat oqova suvlari tarkibidagi og'ir metallar miqdorini doimiy oshirib yuboradigan to'qimachilik (kraska) sexlariga davlat qanday ta'sir chorasi qo'llaydi?", "options": ["Faqat ogohlantiradi", "Sexning faoliyati yopiladi. Zararli moddalarni filtrlaydigan maxsus biologik va kimyoviy (Lokal) tozalash inshootlarini to'liq ishga tushirmagunicha faoliyatiga ruxsat berilmaydi", "Boshqa joyga ko'chiriladi"], "answer_index": 1, "explanation": "To'g'ri! Bo'yoq (to'qimachilik) sexlari suvni eng ko'p zaharlovchilardir, ularga nisbatan nazorat juda qat'iy." },
    { "id": "bpn98", "question": "O'zbekistonda yovvoyi lola (Qizil kitobdagi turlar) ni ildizi bilan yulib bolalariga o'ynagani bergan fuqaro \"bilmasdan\" qilgani uchun jazodan qutuladimi?", "options": ["Ha, bilmagan", "Qonunni bilmaslik javobgarlikdan ozod qilmaydi. Yo'q qilingan lola soniga qarab zarar hisoblanadi va u ma'muriy javobgarlikka (katta jarimaga) tortiladi", "Bolasi yulsa qutuladi"], "answer_index": 1, "explanation": "To'g'ri! Tabiat qonunchiligi qat'iydir, har bir noqonuniy yulish jinoyatga sheriklikdir." },
    { "id": "bpn99", "question": "Shaharsozlikda ekologik qoidaga asosan, agar qurilish firmasi ko'chada daraxt ekadigan bo'lsa (kompensatsiya tarzida) kim uni parvarish qiladi?", "options": ["Hech kim, tabiat o'stiradi", "Qurilish kompaniyasi u ko'chatlarni ekishi, sug'orish tizimini (masalan tomchilatib) o'rnatishi va kamida 3 yil kafolatli parvarish qilib berishi qonun bilan mustahkamlangan", "Hokimiyat"], "answer_index": 1, "explanation": "To'g'ri! Shunchaki ekib tashlab ketish emas, uni ko'kartirish hozirgi kunning qat'iy davlat talabidir." },
    { "id": "bpn100", "question": "Qonun bo'yicha Ekologik qoidabuzarliklarni fotovideofiksatsiya orqali (Eko-nazorat botiga yoki portalga) yuborgan oddiy fuqarolar qanday taqdirlanadi?", "options": ["Rahmat aytiladi", "Huquqbuzardan undirilgan jarima miqdorining 15-20% i miqdorida (pul ko'rinishida) xabar bergan shaxs (jamoatchi ekonazoratchi) hisobiga mukofot tariqasida o'tkazib beriladi", "Hech narsa berilmaydi"], "answer_index": 1, "explanation": "To'g'ri! Bu davlat tomonidan tabiat muhofazasiga jamoatchilikni (fuqarolarni) faol jalb qilishning zamonaviy va samarali tizimidir!" }
