[
    { "id": "btf81", "question": "Plastik idishlarni tashlab yubormaslik uchun ularni ochiq ko'chada yoki uyda olovda yoqish, eng xavfsiz va ekologik toza yo'ldir.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Plastikni ochiq yoqish zaharli 'Dioksin' kabi havoni ifloslantiruvchi moddalarni ishlab chiqaradi. Eng toza usul bu uni qayta ishlashga (Recycling) topshirishdir." },
    { "id": "btf82", "question": "Eski dori-darmonlarni, kimyoviy yuvish vositalarini kanalizatsiya tizimiga yoki oddiy axlatxonaga tashlash suv ekotizimini zaharlashda katta xavf tug'dirmaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Suv tozalash inshootlari kimyoviy dori va zaharlarni filtrlashga moslashmagan. Ular oqova suv orqali daryolarga tushib butun ekotizimni izdan chiqaradi." },
    { "id": "btf83", "question": "Uy elektr asboblari o'chirilgan, lekin rozetkaga tiqilgan (Standby) holatida turganda ham yashirincha ko'p miqdorda elektr energiyasini (Vampir energiya) sarflaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Kompyuter, televizor va zaryadlovchilar o'chirilgan bo'lsa-da energiya yeyishda davom etadi. Bu butun dunyo bo'ylab har yili yuzlab AESlarning bekorga ishlashiga olib kelmoqda." },
    { "id": "btf84", "question": "Faqat birgina insonning energiya, suv va qog'ozni tejashi sayyoradagi global isish jarayoniga umuman ijobiy ta'sir ko'rsata olmaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Aynan har bir individning shaxsiy tanlovi va ongli harakatlari jamiyatda eko-madaniyatni shakllantiradi. Millionlab to'g'ri 'bir kishi'lar iqlim o'zgarishini to'xtatuvchi asosiy kuchdir." },
    { "id": "btf85", "question": "Mikroplastiklar hozirda okeandagi deyarli barcha baliqlarning va ularni iste'mol qiluvchi odamlarning oshqozon-ichak trakti, hatto qoniga ham yetib borgan.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Mikroplastik va nanoplastik zarralari shu qadar kichikki, ular suv aylanish zanjiri orqali ozuqa zanjirining eng yuqori pog'onasidagi inson tanasida o'rnashib olmoqda." },
    { "id": "btf86", "question": "Bioxilmaxillik faqat o'rmonlar uchun muhim, insoniyatning qishloq xo'jaligi uchun uning mutlaqo ahamiyati yo'q.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Agar tabiatdagi yovvoyi changlatuvchilar (asalarilar, qushlar, hasharotlar) hamda tuproq mikroorganizmlari qirilib ketsa, insoniyat ekinlardan hosil ololmay qoladi va ochlik boshlanadi." },
    { "id": "btf87", "question": "Issiqxona effekti (Greenhouse effect) asli tabiat uchun zararli emas, u sayyorani muzlab qolishdan saqlab turuvchi me'yoriy mexanizmdir, xavf uning haddan ortiq kuchayib ketishidadir.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Atmosferada bir oz CO2 va issiqxona gazlari bo'lmaganda edi, Yerning harorati -18 Selsiyni tashkil etib, sayyora o'lik muz qatlamiga aylangan bo'lar edi. Insoniyat bu gazlarni keragidan yuz marta ko'paytirib yubormoqda xolos." },
    { "id": "btf88", "question": "Shaharlarda keng yaproqli daraxtlarni emas, balki ignabargli archalarni ko'p ekish yozning issiq (dim) kunlarida haroratni kuchli mo'tadillashtiradi va havoni ko'proq tozalaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Keng yaproqli daraxtlar (chinor, tut) o'zining katta barg maydoni hisobiga qalin soya tashlaydi va yozda konditsioner kabi namlik tarqatib shaharni sovutadi. Archalar bunday xususiyatga ega emas." },
    { "id": "btf89", "question": "Qizil kitobga kiritilgan o'simlikni emas, faqat uning bargini yoki urug'ini terish qonuniy huquqbuzarlik sanalmaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Noyob o'simlik turlarining urug'i, guli, qismi yoki ildizini yig'ib olish turning tabiiy ko'payishiga qasddan qilingan xavf sifatida baholanib, jarima va zarar undirilishiga asos bo'ladi." },
    { "id": "btf90", "question": "Yovvoyi tabiat qo'yniga (tog'lar, o'rmonlarga) dam olishga borganda pleyer yoxud baland ovozda musiqa yoqish hayvonlarning ko'payish davrini izdan chiqaradigan \"shovqin (akustik) ifloslanish\" sanaladi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Baland sun'iy shovqinlar yovvoyi qushlarni va sut emizuvchilarni qo'rqitadi, ularning inlari (tuxumlari) ni tashlab qochishiga yoki ozuqa topa olmasligiga (aloqa uzilishiga) sabab bo'ladi." },
    { "id": "btf91", "question": "Qishloq xo'jaligida tomchilatib sug'orish tizimi faqatgina suvni tejash uchungina ishlatiladi, uning hosildorlikka va tuproqqa aloqasi yo'q.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Tomchilatib sug'orish suvni 50-70% tejash bilan birga, tuproq eroziyasi va sho'rlanishini to'xtatadi. Shuningdek o'g'it to'g'ri ildizga yetib borgani uchun hosildorlikni 2-3 barobarga oshiradi." },
    { "id": "btf92", "question": "Okeanlardagi marjon qoyalari (Riflar) dunyo okeani bioxilma-xilligining eng ko'p (qariyb 25%) qismini o'zida saqlab turuvchi suv osti \"tropik o'rmonlari\" hisoblanadi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Garchi marjon qoyalari okean tubining juda kichik maydonini egallasa-da, ularsiz butun dengiz ekotizimi va millionlab baliq turlari qirilib ketadi. Hozirda kislotali suv tufayli ular oqarib o'lmoqda." },
    { "id": "btf93", "question": "Agar birorta kompaniya yoki korxona o'z faoliyatida tabiatni asrash choralarini (Green Technologies) ishlatsa, u faqat xarajatga tushadi va hecham daromad ko'rmaydi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Ekologik toza (Yashil) iqtisodiyot uzoq muddatda energiya va xom-ashyoni (chiqindini qayta ishlash hisobiga) juda katta miqdorda tejaydi, jarimalardan qutqaradi va zamonaviy bozorda xaridorlar ishonchini qozonadi." },
    { "id": "btf94", "question": "Daraxt ekish tabiatni qutqarishdagi eng yaxshi amaldir, ammo iqlim va tuproq sharoitiga mos kelmaydigan begona (invaziv) turdagi daraxtlarni ekish foydadan ko'ra ko'proq ziyon keltiradi.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Mahalliy ekotizimga moslashmagan, ko'p suv ichadigan (masalan pavloniya) yoxud mahalliy florani siqib chiqaradigan (invaziv) daraxtlarni ommaviy ekish ekologik fojia (monokultura) ga aylanishi mumkin." },
    { "id": "btf95", "question": "Qayta tiklanuvchi energiya (Shamol, quyosh, geotermal) manbalari sayyorada zaharli issiqxona gazlarini (CO2) ishlab chiqarmaydigan (nol darajali) haqiqiy yashil energetikadir.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Shamol va quyosh panellari o'z ish jarayonida havoga zahar purkamaydi (garchi ularning panellari ishlab chiqarilishida qisman zahar chiqsa ham). Ular ko'mir va gaz stansiyalariga nisbatan yuz barobar toza usuldir." },
    { "id": "btf96", "question": "Insoniyat o'z tarixi davomida tabiatdagi hayvon turlarining genofondiga va ularning populyatsiyasiga hech qanday yirik ta'sir o'tkazmagan.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Inson faoliyati (Antropogen omil) tufayli so'nggi 50 yilda Yerdagi yovvoyi hayvonlar va qushlarning umumi populyatsiyasi qariyb 60-70% ga yo'q bo'lib ketganligi (Oltinchi ommaviy qirilish) Ilmiy jihatdan tasdiqlangan." },
    { "id": "btf97", "question": "Cho'l mintaqasida o'rmon yaratishning iloji yo'q, chunki daraxtlar faqat sernam va yomg'irli joylardagina yirik o'rmon hosil qila oladi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Cho'lning o'ziga xos (Saksovul, qandim kabi daraxt va butalardan tashkil topgan) betakror o'rmonlari bo'ladi. Ular quruq iqlimga moslashgan bo'lib cho'llanish va qum ko'chishini tutib qoluvchi kuchli 'Cho'l o'rmonlari'dir." },
    { "id": "btf98", "question": "O'zbekistonda yovvoyi hayvonlar ovlanadigan qonuniy ruxsatnomalar (kvotalar) faqat davlat byudjetini to'ldirish maqsadida qo'llaniladi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Ov kvotalari eng birinchi navbatda tabiatda qaysidir jonivorning haddan ortiq ko'payib (nazoratsiz populyatsiya) o'rmonga ziyon keltirmasligini nazorat qilish va bio-muvozanatni ushlab turish uchun (Ilmiy xulosalar asosida) beriladi." },
    { "id": "btf99", "question": "Avtomobil oynasidan ko'chaga mayda sigaret qoldig'i (Bichok) ni tashlash kichik huquqbuzarlik bo'lishi bilan birga, sayyoradagi eng ko'p tarqalgan zaharli plastik qoldiqlar (mikroplastik va nikotin filtri) ifloslanishining bosh sababchisidir.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Sigaret filtrlari qog'oz emas, ularda zaharli kimyoviy elementlar bilan to'yingan plastik tolalari mavjud. Ular chirishi uchun o'nlab yillar kerak bo'ladi va ular suvlarni kuchli zaharlaydi." },
    { "id": "btf100", "question": "Men yashab turgan uydagi toza ichimlik suvi (vodoprovod) doimo va hech qachon tugamaydigan mo'l-ko'l manbadan kelib turadi.", "options": ["Rost", "Yolg'on"], "answer_index": 1, "explanation": "Yolg'on! Chuchuk ichimlik suvi Yer yuzidagi eng taqchil (hamma suvning bor-yo'g'i 1% i ichishga yaroqli) resurs bo'lib, iqlim isishi va muzliklar erishi hisobiga hozirgi kunda butun dunyoda, ayniqsa bizning mintaqada uning zaxiralari shiddat bilan tugab bormoqda." }
]
"@

$newQ = ConvertFrom-Json -InputObject $newQuizzesStr
$newP = ConvertFrom-Json -InputObject $newPuzzlesStr
$newT = ConvertFrom-Json -InputObject $newTermsStr
$newPn = ConvertFrom-Json -InputObject $newPenaltiesStr
$newTf = ConvertFrom-Json -InputObject $newTrueFalseStr

$jsonObj.quizzes += $newQ
$jsonObj.puzzles += $newP
$jsonObj.terms += $newT
$jsonObj.penalties += $newPn
$jsonObj.truefalse += $newTf

$jsonObj | ConvertTo-Json -Depth 10 | Set-Content -Path $jsonFile -Encoding UTF8
